
.dh {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.dh__side {
  padding: 6px 8px;
  width: 86%;
}

/* 斜向对立：她压右边线，主角压左边线 */
.dh__side--her {
  align-self: flex-end;
  border-right: 3px solid var(--theme-primary);
}

.dh__side--you {
  align-self: flex-start;
  border-left: 3px solid var(--hud-mute);
}

.dh__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}

.dh__who {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.dh__round {
  font-size: 11px;
}

/* 两条数值条之间留一点缝，别挤成一坨 */
.dh__side :deep(.sb + .sb) {
  margin-top: 4px;
}
