
.sl {
  margin-top: 8px;
}

.sl__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.sl__title {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);

  i {
    margin-right: 4px;
  }
}

.sl__reread {
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 0 6px;
  font: inherit;
  font-size: 11px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  i {
    margin-right: 3px;
  }
}

.sl__list {
  margin-top: 4px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sl__item {
  display: flex;
  gap: 6px;
  align-items: baseline;
  padding: 2px 6px;
  font-size: 12px;
  line-height: 1.5;
  border-left: 2px solid transparent;
  background: var(--hud-bg-2);
}

.sl__item--her {
  border-left-color: var(--theme-primary);
}

.sl__item--you {
  border-left-color: var(--hud-mute);
}

.sl__kind {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
  white-space: nowrap;

  i {
    margin-right: 3px;
  }
}

.sl__text {
  word-break: break-word;
}

.sl__empty,
.sl__error {
  margin-top: 4px;
  font-size: 12px;
  color: var(--hud-mute);
}

.sl__error {
  color: var(--c-danger);

  i {
    margin-right: 3px;
  }
}

.sl__note {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--hud-mute);

  i {
    margin-right: 3px;
  }

  b {
    color: var(--c-warning);
  }
}
