
.tz__reached {
  font-size: 11px;
  color: var(--hud-mute);
  text-align: center;

  i {
    margin-right: 3px;
  }
}

.tz__bars-note {
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);
}

.tz__inner {
  margin-top: 6px;
}

.tz__inner-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: var(--hud-mute);

  i {
    margin-right: 3px;
  }
}

.tz__toggle {
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 0 6px;
  font: inherit;
  font-size: 11px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}

.tz__inner-edit {
  width: 100%;
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  background: var(--hud-bg-2);
  color: var(--hud-text);
  font: inherit;
  font-size: 13px;
  padding: 3px 6px;
  resize: vertical;

  &:focus {
    outline: none;
    border-color: var(--theme-primary);
  }
}

/* 手写体感：斜体 ＋ 稍宽字距 ＋ 一条压在字上的荧光笔痕。
 * 遮住状态只加模糊，不改字号也不换成占位符，才读得出「有话但被盖着」。 */
.tz__inner-text {
  margin-top: 2px;
  padding: 3px 6px;
  font-style: italic;
  letter-spacing: 0.02em;
  white-space: pre-wrap;
  word-break: break-word;
  border-left: 2px solid var(--theme-primary);
  background: var(--theme-soft);
  transition: filter 0.14s ease;
}

.tz__inner-text--veiled {
  filter: blur(3.6px);
  user-select: none;
  cursor: pointer;
}

@media (prefers-reduced-motion: reduce) {
  .tz__inner-text {
    transition: none;
  }
}

.tz__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.tz__note {
  font-weight: 400;
  font-size: 11px;
}

.tz__mismatch {
  font-size: 11px;
  line-height: 1.45;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.tz__skills {
  list-style: none;
}

.tz__skill {
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

.tz__pending {
  font-size: 12px;
  color: var(--c-warning);
}
