
.rs {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  margin-bottom: 8px;
}

/* 编辑态是两行带标签的控件，横排会把 select 压太窄 */
.rs--editing {
  display: block;
  padding: 8px 10px;
}

.rs__stage {
  flex: 0 0 auto;
  font-size: 13px;
  font-weight: 700;
  color: var(--theme-accent);
  white-space: nowrap;

  i {
    margin-right: 4px;
  }
}

.rs__bar {
  flex: 1 1 auto;
}
