
.tp__bars-note {
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);
}

.tp__recover,
.tp__hint {
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);
}

.tp__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.tp__note {
  font-weight: 400;
  font-size: 11px;
}

.tp__slots {
  list-style: none;
}

.tp__slot {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

.tp__slot-key {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
}
