
.sub {
  display: flex;
  gap: 1px;
  padding: 1px;
  margin-bottom: 8px;
  border: 1px solid var(--hud-border);
  border-radius: 3px;
  background: var(--hud-bg-1);
}

.sub__item {
  flex: 1 1 0;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--hud-mute);
  font: inherit;
  font-size: 12px;
  line-height: 1.7;
  padding: 0 4px;
  border-radius: 2px;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  i {
    margin-right: 4px;
  }

  &:hover {
    color: var(--theme-accent);
  }
}

.sub__item--active {
  background: var(--theme-soft);
  color: var(--theme-accent);
  font-weight: 700;
}

/* 右栏本来就窄，装不下三个词时只留图标。
 * 断点比 TabBar 的 340px 高：右栏只占整宽的六成左右，先于整体到达极限。 */
@media (max-width: 460px) {
  .sub__label {
    display: none;
  }

  .sub__item i {
    margin-right: 0;
  }
}
