
/* 语义取色。--sb-color 由下面四条改写，.sb--low 写在最后所以低位优先。 */
.sb--life {
  --sb-color: var(--theme-primary);
}
.sb--energy {
  --sb-color: var(--theme-accent);
}
.sb--affection {
  --sb-color: var(--c-affection);
}
.sb--low {
  --sb-color: var(--c-danger);
}

.sb {
  min-width: 0;
}

.sb__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.sb__label {
  font-size: 12px;
  color: var(--hud-mute);
  white-space: nowrap;

  i {
    color: var(--sb-color);
    margin-right: 3px;
  }
}

.sb__num {
  font-size: 13px;
  color: var(--hud-text);
}

.sb__max {
  color: var(--hud-mute);
  font-size: 11px;
}

.sb__track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-locked);
  border: 1px solid var(--hud-border);
  overflow: hidden;
}

/* 只过渡宽度与颜色，且短：暗线数值不得做庆祝型动效（design-spec §5.8 双线叙事） */
.sb__fill {
  height: 100%;
  background: var(--sb-color);
  transition: width 0.18s ease, background-color 0.12s ease;
}

@media (prefers-reduced-motion: reduce) {
  .sb__fill {
    transition: none;
  }
}

.sb__hint {
  margin-top: 2px;
  font-size: 11px;
  color: var(--hud-mute);
}
