
.eb {
  margin: 6px 0;
  padding: 10px 12px;
  border-left: 3px solid var(--c-danger);
}

.eb__title {
  font-weight: 700;
  color: var(--c-danger);
  margin-bottom: 4px;
}

.eb__msg {
  font-family: var(--font-num);
  font-size: 12px;
  line-height: 1.5;
  color: var(--hud-mute);
  white-space: pre-wrap;
  word-break: break-word;
  margin-bottom: 8px;
}

.eb__retry {
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-text);
  border-radius: 2px;
  padding: 2px 10px;
  font: inherit;
  cursor: pointer;

  &:hover {
    background: var(--theme-soft);
    border-color: var(--theme-primary);
  }
}

.eb__pass {
  display: contents;
}
