
/* 这一页左栏装的是四个下拉＋技能行，比两张脸那两页宽一点才不会每招都折行。 */
.hud-split__side {
  flex-basis: 46%;
  max-width: 250px;
}

.tk__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.tk__note {
  font-weight: 400;
  font-size: 11px;
}

.tk__slots,
.tk__lib {
  list-style: none;
}

.tk__slot {
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

/* 只加缩进，**不动 display**：SkillLine 的根是 flex，`.sl__extra` 靠 `flex: 1 1 100%` 换行，
   在这里改成 block 会把附加效果挤回同一行。 */
.tk__slot-line {
  margin-top: 1px;
  padding-left: 2px;
}

.tk__row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

.tk__row--off {
  opacity: 0.62;
}

.tk__own {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
  cursor: pointer;
  user-select: none;

  input {
    margin-right: 3px;
    vertical-align: -1px;
  }
}

.tk__own-flag {
  flex: 0 0 auto;
  font-size: 11px;
}

.tk__own-flag--yes {
  color: var(--c-success);
}
.tk__own-flag--no {
  color: var(--hud-mute);
}

.tk__equipped {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--theme-accent);
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

/* 数值表：九个字段竖排。`EditableField` 自己是一行 flex，这里只管间距与顶上那条分隔线 */
.tk__spec {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--hud-rule);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* 阵营徽标沿用「在槽」那枚的形状，只换颜色：同一行里两枚形状一致才不显得杂 */
.tk__side {
  flex: 0 0 auto;
  font-size: 11px;
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

.tk__side--her {
  color: var(--theme-accent);
}
.tk__side--you {
  color: var(--hud-mute);
}

.tk__stage {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
}

/* 叙事指导整行独占：它是一段话，挤在数值后面会把每一行都撑成两行 */
.tk__guide {
  flex: 1 1 100%;
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);
}

.tk__del {
  flex: 0 0 auto;
  margin-left: auto;
  border: none;
  background: transparent;
  color: var(--hud-mute);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  padding: 0 2px;

  &:hover {
    color: var(--c-danger);
  }
}

.tk__empty,
.tk__bench,
.tk__hint {
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);
}

.tk__bench {
  margin-top: 4px;
}

.tk__hint {
  margin-top: 6px;

  /* 缺口那句要能被一眼捞出来，但不该重到像警告：只换色不加粗 */
  b {
    color: var(--c-warning);
    font-weight: 400;
  }
}

.tk__warn {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.tk__add {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}

.tk__add-input {
  flex: 1 1 auto;
  min-width: 0;
  font: inherit;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 1px 6px;

  &:focus {
    outline: none;
    border-color: var(--theme-primary);
    box-shadow: 0 0 0 2px var(--theme-soft);
  }
}

.tk__add-btn {
  flex: 0 0 auto;
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 1px 8px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }

  &:not(:disabled):hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}
