
.pb {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);
}

/* 收起态是一条窄行，不是一个主按钮：常态面板的主角是四页数据，不是这个入口 */
.pb__toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  font: inherit;
  font-size: 12px;
  color: var(--hud-mute);
  background: transparent;
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 3px 6px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}

.pb__tease {
  flex: 1 1 auto;
  text-align: right;
  font-size: 11px;
  color: var(--hud-mute);
}

.pb__body {
  margin-top: 6px;
  padding: 8px 10px;
  background: var(--hud-bg-2);
  border: 1px solid var(--theme-primary);
  border-radius: 3px;
}

.pb__lead {
  font-size: 12px;
  line-height: 1.6;

  b {
    color: var(--theme-accent);
  }
}

.pb__stakes {
  margin-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pb__stake {
  display: flex;
  gap: 6px;
  font-size: 12px;
  line-height: 1.5;

  dt {
    flex: 0 0 auto;
    font-weight: 700;
    color: var(--c-success);
    white-space: nowrap;
  }

  dd {
    color: var(--hud-mute);
  }

  i {
    margin-right: 3px;
  }
}

.pb__stake--bad dt {
  color: var(--c-danger);
}

.pb__stake--flat dt {
  color: var(--hud-mute);
}

.pb__judge {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--hud-rule);
  font-size: 11px;
  line-height: 1.6;
  color: var(--hud-mute);

  b {
    color: var(--theme-accent);
  }
}

.pb__warn {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.pb__err {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-danger);

  i {
    margin-right: 3px;
  }
}

.pb__go {
  margin-top: 8px;
  width: 100%;
  padding: 5px 0;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  color: var(--hud-bg-1);
  background: var(--theme-primary);
  border: 1px solid var(--theme-primary);
  border-radius: 2px;
  cursor: pointer;

  &:hover:not(:disabled) {
    background: var(--theme-accent);
    border-color: var(--theme-accent);
  }

  &:disabled {
    cursor: progress;
    opacity: 0.6;
  }

  i {
    margin-right: 4px;
  }
}

.pb__note {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--hud-mute);
}
