
.tb {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--hud-border);
}

.tb__item {
  flex: 1 1 0;
  min-width: 0;
  border: 1px solid transparent;
  border-bottom: none;
  background: transparent;
  color: var(--hud-mute);
  font: inherit;
  font-size: 12px;
  padding: 4px 6px;
  border-radius: 3px 3px 0 0;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  i {
    margin-right: 4px;
  }

  &:hover {
    color: var(--theme-accent);
    background: var(--theme-soft);
  }
}

.tb__item--active {
  color: var(--theme-accent);
  background: var(--hud-bg-2);
  border-color: var(--hud-border);
  font-weight: 700;
  /* 压住下方那条描边，做出「这页是连着面板的」纸片感 */
  margin-bottom: -1px;
  padding-bottom: 5px;
}

/* 窄屏只留图标，四页不换行 */
@media (max-width: 340px) {
  .tb__label {
    display: none;
  }
}
