
.sl {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
}

.sl__empty {
  color: var(--hud-mute);
  font-size: 12px;
}

.sl__name {
  font-weight: 700;
}

.sl__kind {
  font-size: 11px;
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

.sl__kind--atk {
  color: var(--c-danger);
}
.sl__kind--sup {
  color: var(--theme-accent);
}
.sl__kind--unknown {
  color: var(--c-warning);
}

.sl__nums {
  font-size: 12px;
  color: var(--hud-mute);
}

.sl__extra {
  flex: 1 1 100%;
  font-size: 11px;
  color: var(--hud-mute);
}
