
.et {
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--hud-rule);
}

.et__row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.et__title {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--theme-accent);
}

.et__btn {
  flex: 0 0 auto;
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 1px 8px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    background: var(--theme-soft);
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}

.et__btn--primary {
  border-color: var(--theme-primary);
  color: var(--theme-accent);
  font-weight: 700;
}

/* 只在编辑态露出的一行说明。压成灰小字，免得比它上面那行标题还抢眼。 */
.et__note {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--hud-mute);

  i {
    margin-right: 3px;
  }
}
