
.te__block {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);

  &:first-of-type {
    margin-top: 0;
    padding-top: 0;
    border-top: none;
  }
}

.te__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.te__note {
  font-weight: 400;
  font-size: 11px;
}

.te__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* 便利贴：左侧一道赭黄压边，和常态纸面拉开一层 */
.te__item {
  padding: 5px 8px;
  border-left: 3px solid var(--theme-primary);
}

.te__item--done {
  border-left-color: var(--c-success);
  opacity: 0.78;
}

.te__name {
  font-weight: 700;
  word-break: break-word;
}

.te__progress {
  font-size: 12px;
  color: var(--hud-mute);
  white-space: pre-wrap;
  word-break: break-word;
}

.te__empty {
  font-size: 12px;
  color: var(--hud-mute);
}

.te__name-input,
.te__progress-input {
  display: block;
  width: 100%;
  font: inherit;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 1px 6px;

  &:focus {
    outline: none;
    border-color: var(--theme-primary);
    box-shadow: 0 0 0 2px var(--theme-soft);
  }
}

.te__name-input {
  font-weight: 700;
}

.te__progress-input {
  margin-top: 3px;
  resize: vertical;
  line-height: 1.5;
  font-size: 12px;
}

.te__ops {
  display: flex;
  gap: 6px;
  margin-top: 4px;
}

.te__op {
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 0 6px;
  font: inherit;
  font-size: 11px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  i {
    margin-right: 3px;
  }
}

.te__op--del:hover {
  border-color: var(--c-danger);
  color: var(--c-danger);
}

.te__add {
  margin-top: 6px;
  border: 1px dashed var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 1px 8px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  i {
    margin-right: 3px;
  }
}

.te__warn {
  margin-top: 4px;
  font-size: 11px;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.te__fold {
  display: block;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--hud-mute);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  padding: 0;

  &:hover {
    color: var(--theme-accent);
  }

  i {
    margin-right: 4px;
    width: 9px;
  }
}

.te__list--history {
  margin-top: 6px;
}
