
.bg__title {
  font-size: 12px;
  color: var(--hud-mute);
  font-weight: 700;
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.bg__note {
  font-weight: 400;
  font-size: 11px;
}

.bg__list {
  list-style: none;
}

.bg__slot {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

.bg__slot--empty {
  color: var(--hud-mute);
}

.bg__empty {
  font-size: 12px;
}

.bg__name {
  font-weight: 700;
}

.bg__tier {
  font-size: 11px;
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

.bg__tier--common {
  color: var(--hud-mute);
}
.bg__tier--fine {
  color: var(--theme-accent);
}
.bg__tier--rare {
  color: var(--c-affection);
}
.bg__tier--offfield {
  color: var(--c-success);
}
.bg__tier--unknown {
  color: var(--c-warning);
}

.bg__count {
  font-size: 12px;
}

.bg__effect {
  flex: 1 1 100%;
  font-size: 11px;
  color: var(--hud-mute);
}

.bg__warn {
  margin-top: 4px;
  font-size: 11px;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}
