
.pf {
  min-width: 0;
}

.pf__box {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--hud-border);
  border-radius: 3px;
  background: var(--c-locked);
  color: var(--hud-border); /* 供轮廓 currentColor 取用 */
}

.pf__outline,
.pf__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.pf__outline {
  fill: none;
  stroke: currentcolor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  padding: 8%;
}

.pf__img {
  background-size: cover;
  background-position: center top;
  background-repeat: no-repeat;
}

.pf--she .pf__img {
  background-image: var(--portrait-she);
}

/* 主角是背面剪影：没有图时把轮廓压暗一档，和她的正面框区分开 */
.pf--you .pf__img {
  background-image: var(--portrait-you);
}

.pf--you .pf__box {
  color: var(--hud-mute);
}

.pf__caption {
  margin-top: 4px;
  font-size: 11px;
  color: var(--hud-mute);
  text-align: center;
}
