
.bp__silhouette {
  margin: 8px auto 0;
  width: 38%;
  max-width: 120px;
}

/* 判档结果贴着对局面板走：它解释的就是上面那条血条的分母 */
.bp__tier {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--hud-mute);

  i {
    margin-right: 3px;
  }
}

/* 兜底那一层是要人动手的，不能跟普通说明一个颜色 */
.bp__tier--warn {
  color: var(--c-warning);
}

.bp__form {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bp__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--theme-accent);
}

.bp__h--gap {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);
}

.bp__note {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--hud-mute);
}
